import{_ as o,o as t,c as s,a2 as a}from"./chunks/framework.CqdVOxXJ.js";const r="/rakkii-cars-guide/screenshots/v2/a16-released.png",n="/rakkii-cars-guide/screenshots/v2/a18-job-history.png",k=JSON.parse('{"title":"8. Mark the job done","description":"","frontmatter":{},"headers":[],"relativePath":"desk/job/08-mark-done.md","filePath":"desk/job/08-mark-done.md","lastUpdated":1794621279000}'),i={name:"desk/job/08-mark-done.md"};function l(d,e,h,g,c,p){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="_8-mark-the-job-done" tabindex="-1">8. Mark the job done <a class="header-anchor" href="#_8-mark-the-job-done" aria-label="Permalink to &quot;8. Mark the job done&quot;">​</a></h1><p><strong>Who:</strong> Owner or admin · <strong>Where:</strong> the job&#39;s <strong>Release</strong> tab · <strong>Status after:</strong> Done</p><p>A car can leave before everything is settled, for example while an insurer still has to pay. So:</p><ul><li><strong>Released</strong> means the car is out.</li><li><strong>Done</strong> means nothing is left on the job.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Open the released job. The progress card lists anything still open: checklist items, balances, unpaid suppliers or a payment proof to review. When it says <strong>Nothing left. Ready to mark as done.</strong>, you&#39;re clear.</li><li>Press <strong>Mark as done</strong> (on the <strong>Release</strong> tab, or the <strong>Mark as done →</strong> button at the top).</li><li>The app asks &quot;Mark this job as done?&quot; and reminds you a done job is read-only. Press <strong>Mark as done</strong> again.</li></ol><p><img src="'+r+'" alt="Released job: Nothing left. Ready to mark as done."></p><p>The job moves to <strong>Done</strong> and shows in <strong>Workshop › Job history</strong>.</p><p><img src="'+n+'" alt="Job history with the done job at the top"></p><h2 id="what-blocks-it" tabindex="-1">What blocks it <a class="header-anchor" href="#what-blocks-it" aria-label="Permalink to &quot;What blocks it&quot;">​</a></h2><ul><li><strong>Only open checklist items block Mark as done.</strong> Money still owed is listed but doesn&#39;t block, because insurers can pay long after release.</li><li>With checklist items open, only the owner can mark it done, by typing a reason. The reason is saved in the job&#39;s <strong>Status log</strong>.</li></ul><p>A done job is read-only. It stays in the customer&#39;s history and in <strong>Job history</strong>.</p><h2 id="need-to-change-a-released-job" tabindex="-1">Need to change a released job? <a class="header-anchor" href="#need-to-change-a-released-job" aria-label="Permalink to &quot;Need to change a released job?&quot;">​</a></h2><p>The owner can press <strong>Unlock</strong> in the job header. The old release is kept as history (<strong>Previous release</strong>).</p><p><strong>Back to:</strong> <a href="/rakkii-cars-guide/desk/">Your day at the desk</a></p>',15)])])}const u=o(i,[["render",l]]);export{k as __pageData,u as default};
